// @param float _Angle = 90 [-360 .. 360]
// @param transform2D _Area = (0.5, 0.5, 0.6, 0.6, 0)
float4 ApplyFX(float2 uv, float4 color)
{
    float2 p = _Area_ToLocal(uv) - 0.5;
    float weight = saturate(1 - length(p) * 2);
    float angle = radians(_Angle) * weight * weight;
    float s = sin(angle), c = cos(angle);
    float2 q = float2(c * p.x - s * p.y, s * p.x + c * p.y);
    return SampleInput(_Area_ToInput(q + 0.5));
}
